CREATE FUNCTION public.calculate_warranty_expiry(p_start_date date, p_warranty_months integer DEFAULT 3) RETURNS date
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN p_start_date + (p_warranty_months * INTERVAL '1 month') - INTERVAL '1 day';
END;
$$;


