--
-- TOC entry 394 (class 1255 OID 28175)
-- Name: sync_tech_avail_status(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.sync_tech_avail_status() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
    BEGIN
      IF NEW.is_available THEN
        UPDATE technicians SET availability_status = 'available', updated_at = now()
        WHERE technician_id = NEW.technician_id;
      ELSE
        UPDATE technicians SET availability_status = 'on_leave', updated_at = now()
        WHERE technician_id = NEW.technician_id;
      END IF;
      RETURN NEW;
    END;
    $$;


ALTER FUNCTION public.sync_tech_avail_status() OWNER TO postgres;

