CREATE FUNCTION public.update_challan_totals() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
      DECLARE
          target_id INT;
      BEGIN
          IF (TG_OP = 'DELETE') THEN
              target_id := OLD.delivery_challan_id;
          ELSE
              target_id := NEW.delivery_challan_id;
          END IF;

          UPDATE delivery_challans
          SET total_quantity = (
              SELECT COALESCE(SUM(quantity), 0)
              FROM delivery_challan_items
              WHERE delivery_challan_id = target_id
          ),
          total_amount = (
              SELECT COALESCE(SUM(quantity * COALESCE(unit_price,
                  (SELECT selling_price FROM parts WHERE part_id = delivery_challan_items.part_id)
              )), 0)
              FROM delivery_challan_items
              WHERE delivery_challan_id = target_id
          )
          WHERE delivery_challan_id = target_id;

          IF (TG_OP = 'DELETE') THEN
              RETURN OLD;
          ELSE
              RETURN NEW;
          END IF;
      END;
      $$;


